"<!DOCTYPE html>
<html><head><title>Analyze</title>
<script src="https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js"></script>
</head><body>
<h2>Analyzing Excel file...</h2>
<pre id="output" style="white-space:pre-wrap;font-size:12px;max-height:90vh;overflow:auto;"></pre>
<script>
async function analyze() {
  const out = document.getElementById('output');
  try {
    const resp = await fetch('sample_data.xlsx');
    const buf = await resp.arrayBuffer();
    const wb = XLSX.read(new Uint8Array(buf), { type: 'array', cellDates: true });

    let text = '';
    text += `=== SHEET NAMES (${wb.SheetNames.length}) ===\n`;
    wb.SheetNames.forEach((name, i) => {
      text += `  ${i+1}. "${name}"\n`;
    });
    text += '\n';

    wb.SheetNames.forEach(name => {
      const ws = wb.Sheets[name];
      const data = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
      text += `\n=== SHEET: "${name}" === (${data.length} rows total)\n`;

      if (data.length === 0) {
        text += '  (empty sheet)\n';
        return;
      }

      // Show first 8 rows
      const showRows = Math.min(8, data.length);
      for (let r = 0; r < showRows; r++) {
        const row = data[r];
        text += `  Row ${r}: [`;
        if (row) {
          row.forEach((cell, ci) => {
            let val = cell;
            if (val instanceof Date) val = val.toISOString().slice(0,10);
            val = String(val ?? '');
            if (val.length > 50) val = val.slice(0,50) + '...';
            text += `"${val}"`;
            if (ci < row.length - 1) text += ', ';
          });
        }
        text += ']\n';
      }
      // Max column count
      const maxCols = Math.max(...data.map(r => (r || []).length));
      text += `  Max columns: ${maxCols}\n`;
      text += `  Total rows: ${data.length}\n`;
    });

    out.textContent = text;
    console.log(text);
  } catch(e) {
    out.textContent = 'Error: ' + e.message;
  }
}
analyze();
